import json,os,sys,hashlib,glob,math
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from lib import T,TL,B,A,P,S,F,IMG,CHECK,AN,PF,LEAD
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT=f'{ROOT}/courses/microprocessors'
SL=f'{ROOT}/tools/slides-08'
course={"id":"microprocessors","name":"Микропроцессорлық жүйелер","lang":"kk","space":"courses"}
def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def DEM(t):return f'<p><b>Демек: {t}</b></p>'
def CODE(t):return f'<pre><code>{t}</code></pre>'

# ---------- numbers, recomputed ----------
assert 100+100==200 and format(200,'08b')=='11001000' and 200-256==-56          # R1=100, [A]=100 -> 200; signed -56: N=1, V=1, C=0, Z=0
assert 6*0.5==3.0 and 1/2e9==0.5e-9                                              # ADD 6 tacts at 2 GHz = 3 ns
assert math.ceil(math.log2(6))==3 and math.ceil(math.log2(4))==2                 # tact counter bits
assert round(1/1.2e-9/1e6)==833                                                  # T>=1.2 ns -> f<=833 MHz
assert 3+1==4                                                                    # ADD R1,R2: 3 fetch + 1 execute
# loop R3: 3 -> 0 with microinstructions 20 (dec) and 21 (branch if Z=0 -> 20)
r3=3;mkar=20;trace=[]
while True:
    if mkar==20:r3-=1;trace.append((20,r3));mkar=21
    elif mkar==21:
        trace.append((21,r3))
        if r3!=0:mkar=20
        else:mkar=22;break
assert [t[0] for t in trace]==[20,21,20,21,20,21] and r3==0 and mkar==22 and len(trace)==6 and [t[1] for t in trace if t[0]==20]==[2,1,0]
# format sizes (example): 64 signals; vertical = 4 fields x 4 bit; BK 3 bit; KMKA 10 bit (1024 addresses)
hw=64+3+10;vt=4*4+3+10;assert (hw,vt)==(77,29) and 2**10==1024 and 2**4==16 and 4*16==64
assert hw*1024==78848 and 78848//8==9856 and vt*1024==29696 and 29696//8==3712 and round((9856-3712)/9856*100)==62
# shared fetch: 3 shared + 100 commands x 3 own = 303 vs 100 x 6 = 600
assert 3+100*3==303 and 100*6==600
# overlap: tf=1.2, te=0.8, 3 microinstructions
tf,te=1.2,0.8;assert round(3*(tf+te),1)==6.0 and round(tf+2*tf+te,1)==4.4
assert round(6*1.2,1)==7.2

